    @Test
    public void testCountFieldsToPrint_StopAtZeroOrLess_ReturnsZero() {
        FieldFormatter fieldFormatter = mock(FieldFormatter.class);
        ReadablePeriod period = mock(ReadablePeriod.class);
        Locale locale = Locale.getDefault();

        // Case: stopAt <= 0
        assertEquals(0, fieldFormatter.countFieldsToPrint(period, 0, locale));
        assertEquals(0, fieldFormatter.countFieldsToPrint(period, -1, locale));
    }

