        FieldFormatter fieldFormatter = mock(FieldFormatter.class, CALLS_REAL_METHODS);
        ReadablePeriod period = mock(ReadablePeriod.class);
        Locale locale = Locale.getDefault();

        // To cover the logic: if (stopAt > 0 && iPrintZeroSetting == PRINT_ZERO_ALWAYS) return 1
